use vstd::prelude::*;
use builtin::vec::*;
use builtin::nat::*;

/// Given:
///  - a non‐empty vector `indices` of row‐selectors (u8),
///  - a non‐empty matrix `choices` as a vector of rows, each row being
///    a vector of f64 values,
/// with the guarantees:
///  1) `choices` has at least one row,
///  2) every row in `choices` has length exactly `indices.len()`,
///  3) each `indices[i]` is a valid row number into `choices`,
/// this function builds a new vector `res` of length `indices.len()` such that
/// for each index `i`,  
///    res[i] == choices[ indices[i] as usize ][ i ].
verus! {
    pub fn choose(indices: Vec<u8>, choices: Vec<Vec<f64>>) -> Vec<f64>
        // Pre‐conditions
        requires indices.len() >= 1
        requires choices.len() >= 1
        requires forall |r: usize| r < choices.len() ==> choices[r].len() == indices.len()
        requires forall |i: usize| i < indices.len() ==> (indices[i] as usize) < choices.len()
        // Post‐conditions
        ensures |res: &Vec<f64>| res.len() == indices.len()
        ensures |res: &Vec<f64>| forall |i: usize| i < indices.len() ==>
                                  res[i] == choices[(indices[i] as usize)][i]
    {
        let n = indices.len();
        let mut res: Vec<f64> = Vec::new();
        let mut i: usize = 0;

        // Build result one entry at a time
        while i < n {
            invariant i <= n
            invariant res.len() == i
            invariant forall |j: usize| j < i ==>
                                  res[j] == choices[(indices[j] as usize)][j]
            decreases n - i;
            {
                let row = indices[i] as usize;
                let v = choices[row][i];
                res.push(v);
                i += 1;
            }
        }

        res
    }
}